"""Four synchronized original RGB source streams for heavy marked-lane cases."""

from __future__ import annotations

import subprocess
from pathlib import Path
from threading import Condition
from time import monotonic


CAMERAS = {
    "overview": ((-8, 0, 8), (-12, 0, 0), (1920, 1080), 95),
    "approach": ((1.2, 0, 2), (0, 0, 0), (1280, 720), 90),
    "reference_corner": ((-3, 2.5, 2.6), (-7, 0, 0), (1280, 720), 100),
    "driver_reference": ((0.6, -0.35, 1.6), (0, 0, 0), (1280, 720), 85),
}


class LosslessSourceSink:
    def __init__(self, output, name, *, popen=subprocess.Popen):
        if name not in CAMERAS:
            raise ValueError("Unknown heavy-lane source camera")
        path = Path(output) / (name + ".mkv")
        if path.exists():
            raise ValueError("Retain prior heavy-lane camera source")
        width, height = CAMERAS[name][2]
        self.frame_bytes = width * height * 4
        self.process = popen(["ffmpeg", "-nostdin", "-loglevel", "error", "-y",
                              "-f", "rawvideo", "-pixel_format", "bgra",
                              "-video_size", f"{width}x{height}", "-framerate", "20",
                              "-i", "pipe:0", "-an", "-c:v", "ffv1", str(path)],
                             stdin=subprocess.PIPE)
        self.closed = False

    def write(self, image):
        if self.closed or len(image.raw_data) != self.frame_bytes:
            raise ValueError("Original heavy-lane camera byte count changed")
        self.process.stdin.write(image.raw_data)

    def close(self):
        if not self.closed:
            self.closed = True
            self.process.stdin.close()
            if self.process.wait() != 0:
                raise ValueError("Lane source encoder failed")


class HeavyLaneCameraCapture:
    def __init__(self, world, carla_module, ego, sinks):
        if set(sinks) != set(CAMERAS):
            raise ValueError("Exactly four named lane source sinks required")
        self.sinks = sinks
        self.frames = {name: set() for name in CAMERAS}
        self.condition = Condition()
        self.errors = []
        self.sensors = []
        self.closed = False
        try:
            for name, (loc, rot, size, fov) in CAMERAS.items():
                blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
                for key, value in (("image_size_x", size[0]), ("image_size_y", size[1]),
                                   ("fov", fov), ("sensor_tick", 0.05)):
                    blueprint.set_attribute(key, str(value))
                transform = carla_module.Transform(
                    carla_module.Location(*loc), carla_module.Rotation(*rot))
                sensor = world.spawn_actor(blueprint, transform, attach_to=ego)
                self.sensors.append(sensor)
                sensor.listen(lambda image, source=name: self._receive(source, image))
        except BaseException:
            self.close()
            raise

    def _receive(self, name, image):
        with self.condition:
            if self.closed:
                return
            try:
                if image.frame in self.frames[name]:
                    raise ValueError("Duplicate original heavy-lane camera frame")
                if (image.width, image.height) != CAMERAS[name][2]:
                    raise ValueError("Original heavy-lane camera dimensions changed")
                self.sinks[name].write(image)
                self.frames[name].add(image.frame)
            except BaseException as error:
                self.errors.append(error)
            finally:
                self.condition.notify_all()

    def wait_for_frame(self, frame, *, timeout_s=10):
        deadline = monotonic() + timeout_s
        with self.condition:
            while True:
                if self.errors:
                    raise ValueError("Lane source camera callback failed") from self.errors[0]
                if all(frame in observed for observed in self.frames.values()):
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    raise ValueError("Missing original heavy-lane source camera frame")
                self.condition.wait(remaining)

    def verify(self, frames):
        expected = set(frames)
        if not expected or any(observed != expected for observed in self.frames.values()):
            raise ValueError("Missing or extra original heavy-lane camera frames")
        return {name: len(expected) for name in CAMERAS}

    def close(self):
        if not self.closed:
            self.closed = True
            for sensor in reversed(self.sensors):
                sensor.stop()
                sensor.destroy()

"""Original map turn plan and per-tick commanded/read-back turn intent."""

from __future__ import annotations

from hashlib import sha256
import json
from math import atan2, degrees, isfinite
from pathlib import Path


def _heading(waypoint):
    forward = waypoint.transform.get_forward_vector()
    return atan2(float(forward.y), float(forward.x))


def _angle(a, b):
    from math import pi
    return (b - a + pi) % (2 * pi) - pi


def select_turn_plan(route, *, step_m):
    """Find a downstream connected road turn; reject a straight continuation."""
    if len(route) < 2 or not isfinite(step_m) or step_m <= 0:
        raise ValueError("Original route and positive turn survey step required")
    origin = route[-1]
    start = _heading(origin)
    frontier = [(origin, 0)]
    seen = set()
    while frontier:
        waypoint, depth = frontier.pop(0)
        identity = (int(waypoint.road_id), int(waypoint.lane_id), round(float(waypoint.s), 1))
        if identity in seen or depth > 100:
            continue
        seen.add(identity)
        change = degrees(_angle(start, _heading(waypoint)))
        if 25 <= abs(change) <= 155 and int(waypoint.road_id) != int(origin.road_id):
            location = waypoint.transform.location
            return {"requested_movement": "turn", "direction": "left" if change > 0 else "right",
                    "origin_road_id": int(origin.road_id), "origin_lane_id": int(origin.lane_id),
                    "destination_road_id": int(waypoint.road_id),
                    "destination_lane_id": int(waypoint.lane_id),
                    "destination_xyz_m": [float(location.x), float(location.y), float(location.z)],
                    "heading_change_deg": change, "map_geometry_observed": True,
                    "lawful_turn_premise": None}
        if depth < 100:
            frontier.extend((candidate, depth + 1) for candidate in waypoint.next(step_m))
    raise ValueError("No downstream connected turning movement in selected Native route")


def save_turn_plan(path, plan):
    if plan.get("lawful_turn_premise") is not None or plan.get("direction") not in ("left", "right"):
        raise ValueError("Turn plan must leave independent legal permission open")
    target = Path(path)
    target.write_text(json.dumps(plan, indent=2, allow_nan=False) + "\n")
    return sha256(target.read_bytes()).hexdigest()


def turn_intent_row(frame, time_s, plan_sha256, ego, command, direction):
    """Record operator command and Native indicator readback as separate facts."""
    if direction not in ("left", "right") or not isinstance(command, dict):
        raise ValueError("Missing source-recorded turn command")
    transform = ego.get_transform()
    location = transform.location
    return {"frame": int(frame), "time_s": float(time_s), "turn_plan_sha256": plan_sha256,
            "requested_direction": direction, "command": command,
            "indicator_readback": str(ego.get_light_state()),
            "ego_xyz_m": [float(location.x), float(location.y), float(location.z)],
            "ego_heading_deg": float(transform.rotation.yaw),
            "lawful_turn_premise": None}
